enum anytty_status_v1 {
  ANYTTY_STATUS_OK(0),
  ANYTTY_STATUS_INVALID_ARGUMENT(1),
  ANYTTY_STATUS_INVALID_HANDLE(2),
  ANYTTY_STATUS_CLOSED(3),
  ANYTTY_STATUS_CAPACITY(4),
  ANYTTY_STATUS_INTERNAL(5);

  final int value;
  const anytty_status_v1(this.value);

  static anytty_status_v1 fromValue(int value) => switch (value) {
    0 => ANYTTY_STATUS_OK,
    1 => ANYTTY_STATUS_INVALID_ARGUMENT,
    2 => ANYTTY_STATUS_INVALID_HANDLE,
    3 => ANYTTY_STATUS_CLOSED,
    4 => ANYTTY_STATUS_CAPACITY,
    5 => ANYTTY_STATUS_INTERNAL,
    _ => throw ArgumentError('Unknown value for anytty_status_v1: $value'),
  };
}

